import{z as i,x as B,o as s,c as p,q as r,j as n,D as E,d as t,s as l,S as A,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"Lampson 保护","description":"","frontmatter":{"title":"Lampson 保护","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/lampson-protection.md","filePath":"cs/lampson-protection.md","lastUpdated":1791063341000}'),d={name:"cs/lampson-protection.md"};function m(c,a,h,C,D,f){const o=B("Mermaid");return s(),p("div",null,[a[2]||(a[2]=r('<h1 id="lampson-保护" tabindex="-1">Lampson 保护 <a class="header-anchor" href="#lampson-保护" aria-label="Permalink to &quot;Lampson 保护&quot;">​</a></h1><div class="epigraph"><p>保护是主体、客体与权利的矩阵；机制应能表达政策，而不把政策焊死在某一种操作系统里。</p><footer>—— Lampson, Protection, 1971；重刊 ACM Operating Systems Review, 1974</footer></div><p><a href="/cs/lamport-clocks">上一课</a>附录对照了无共享时钟时的因果。附录对照，不插入主干。主干已在<a href="/cs/acl-least-priv">访问控制与最小特权</a>、<a href="/cs/dac-mac-rbac">DAC/MAC/RBAC</a>、<a href="/cs/capability-vs-acl">能力对 ACL</a>里用过保护矩阵与两种存放；这里对照 <strong>Lampson 原文的问题</strong>：如何把「谁可以对什么做什么」写成可实现的抽象，并讨论域切换与放大。不重做 Unix mode。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Lamport 处理事件序，不处理授权。Lampson 的缺口是保护：访问矩阵、域、把矩阵按列存成 ACL、按行发成能力，以及从用户态进入更特权域的受控门。主干安全课在数据库之后才命名 CIA，但矩阵观念来自这篇。附录只对照原文如何把保护从「操作系统功能列表」里抽成对象。</p><p><span class="marginnote">Saltzer 与 Schroeder 1975 把最小特权等原则写成更长的教程。Lampson 更短、更机制。不要给两篇发明编号。</span></p><p><span class="marginnote">术语翻译：访问矩阵的「行」是一个主体在所有客体上的全部权利（发出去就是能力），「列」是一个客体上所有能碰它的主体名单（存下来就是 ACL）。同一个矩阵，按行切还是按列切，就决定了系统里谁来保存这张授权单。</span></p><p><span class="marginnote">数字实例：3 个用户、4 个文件的保护矩阵共有 \\(3 \\times 4 = 12\\) 个条目。真实系统里绝大多数条目是空的——1000 个用户对 100 万个文件就是 10 亿个格子，几乎全是「无权利」。这解释了为什么没有系统真的存整个矩阵，而只存稀疏的行或列。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>矩阵条目是权利。当前域决定能用哪一行。系统调用是换域。能力必须不可伪造（标签、加密、或硬件）。主干能力课已取用「持票即允许」；ACL 课取用按客体存名单。本附录不把 RBAC 写回 1971。</p>',10)),(s(),n(A,null,{default:E(()=>[l(o,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20MAT%5B%22%E4%B8%BB%E4%BD%93%20x%20%E5%AE%A2%E4%BD%93%E7%9A%84%E6%9D%83%E5%88%A9%22%5D%20--%3E%20ACL%5B%22%E6%8C%89%E5%88%97%3A%20ACL%22%5D%0A%20%20MAT%20--%3E%20CAP%5B%22%E6%8C%89%E8%A1%8C%3A%20%E8%83%BD%E5%8A%9B%22%5D%0A%20%20GATE%5B%22%E5%8F%97%E6%8E%A7%E6%8D%A2%E5%9F%9F%22%5D%20--%3E%20TRUNK%5B%22%E4%B8%BB%E5%B9%B2%3A%20%E7%89%B9%E6%9D%83%E7%BA%A7%E4%B8%8E%E7%B3%BB%E7%BB%9F%E8%B0%83%E7%94%A8%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"一旦保护是矩阵，完整中介、失败安全、最小特权才有落点。THE 分层是结构；Lampson 补的是权利语言。后文 Cerf–Kahn 管互联，不管矩阵——所以安全课不能提前用 1974 网络文代替本篇。",-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"常见误区：初学者容易把系统调用当成普通函数调用。实际上它是一次受控换域——函数调用只换了代码位置，系统调用却把 CPU 的特权级整个换了，进入的是另一个保护域。门（gate）的作用就是保证这次换域只能走系统规定好的入口、拿到规定好的权利，而不是把内核的全部权力交给调用者。")],-1)),(s(),n(A,null,{default:E(()=>[l(o,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E7%94%A8%E6%88%B7%E8%BF%9B%E7%A8%8B%20(%E5%9F%9F%20D1)%22%5D%20--%3E%7C%22%E6%89%A7%E8%A1%8C%E7%B3%BB%E7%BB%9F%E8%B0%83%E7%94%A8%22%7C%20G%5B%22%E5%8F%97%E6%8E%A7%E9%97%A8%3A%20%E6%A3%80%E6%9F%A5%E5%8F%82%E6%95%B0%E4%B8%8E%E5%85%A5%E5%8F%A3%22%5D%0A%20%20G%20--%3E%7C%22%E5%90%88%E6%B3%95%3A%20%E6%94%BE%E5%A4%A7%E6%9D%83%E5%88%A9%22%7C%20K%5B%22%E5%86%85%E6%A0%B8%20(%E5%9F%9F%20D0)%22%5D%0A%20%20K%20--%3E%20S%5B%22%E4%BB%A3%E4%B8%BA%E8%AE%BF%E9%97%AE%E5%AE%A2%E4%BD%93%22%5D%0A%20%20S%20--%3E%7C%22%E8%BF%94%E5%9B%9E%E7%BB%93%E6%9E%9C%E5%B9%B6%E9%99%8D%E5%9B%9E%E6%9D%83%E5%88%A9%22%7C%20P%0A%20%20P%20-.-%3E%7C%22%E8%AF%95%E5%9B%BE%E7%9B%B4%E6%8E%A5%E8%AE%BF%E9%97%AE%E5%86%85%E6%A0%B8%E5%AE%A2%E4%BD%93%22%7C%20DENY%5B%22%E7%A1%AC%E4%BB%B6%E6%8B%92%E7%BB%9D%3A%20%E8%B6%8A%E6%9D%83%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p>上面这张图回答的问题是：一次受控换域里权利如何先放大再收回。普通域切换（如进程间切换）是平级换身份，门切换是低特权域借高特权域的手办事，办事结束后权利必须降回来，否则用户程序就永久偷走了内核的权利。</p><h3 id="为何对照而不插入主干" tabindex="-1">为何对照而不插入主干 <a class="header-anchor" href="#为何对照而不插入主干" aria-label="Permalink to &quot;为何对照而不插入主干&quot;">​</a></h3><p>主干按系统栈：先比特与 OS 隔离硬件，安全课在库之后才开 CIA。把 1971 插在 THE 之后当必修「下一课」，会让读者以为保护是 OS 附录而不是安全主干。本篇只对照原文对象。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把 1971 与 Bell–LaPadula 混成一篇。也不要在附录里开信息流形式语义。下一篇对照 Cerf–Kahn 1974 分组互联。</p><p>对照结束应回到主干<a href="/cs/acl-least-priv">访问控制</a>与<a href="/cs/privilege-rings">特权级</a>。保护矩阵不插入网络课中间。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>附录对照 Lampson 1971/1974：保护 = 矩阵 + 换域。</li><li>主干 ACL/能力课已取用；本篇不插入安全课之前当课序。</li><li>出处：Lampson, Protection, 1971/1974。</li></ul>',8))])}const L=i(d,[["render",m]]);export{_ as __pageData,L as default};
